import pytest


def create_task(client, title="Original title"):
    response = client.post("/tasks", json={"title": title})
    assert response.status_code == 201
    return response.json()


def assert_saved_task(client, expected):
    response = client.get(f"/tasks/{expected['id']}")
    assert response.status_code == 200
    assert response.json() == expected


@pytest.mark.parametrize("title", ["x", "x" * 100, "  Updated title \t\n"])
def test_patch_title_trims_and_preserves_omitted_fields(client, title):
    original = create_task(client)
    response = client.patch(
        f"/tasks/{original['id']}", json={"done": True}
    )
    assert response.status_code == 200
    original = response.json()

    response = client.patch(
        f"/tasks/{original['id']}", json={"title": title}
    )

    expected = {**original, "title": title.strip()}
    assert response.status_code == 200
    assert response.json() == expected
    assert_saved_task(client, expected)


def test_patch_done_toggles_both_directions_preserving_other_fields(client):
    original = create_task(client)

    for done in (True, False):
        response = client.patch(
            f"/tasks/{original['id']}", json={"done": done}
        )
        expected = {**original, "done": done}
        assert response.status_code == 200
        assert response.json() == expected
        assert response.json()["done"] is done
        assert_saved_task(client, expected)


def test_patch_updates_title_and_done_together(client):
    original = create_task(client)

    response = client.patch(
        f"/tasks/{original['id']}",
        json={"title": "  New title  ", "done": True},
    )

    expected = {**original, "title": "New title", "done": True}
    assert response.status_code == 200
    assert response.json() == expected
    assert_saved_task(client, expected)


@pytest.mark.parametrize("title", ["", " \t\n ", "x" * 101])
def test_patch_invalid_title_does_not_partially_update_done(client, title):
    original = create_task(client)

    response = client.patch(
        f"/tasks/{original['id']}",
        json={"title": title, "done": True},
    )

    assert response.status_code == 422
    assert "detail" in response.json()
    assert_saved_task(client, original)


def test_patch_title_limit_is_applied_after_trimming(client):
    original = create_task(client)
    title = "x" * 100

    response = client.patch(
        f"/tasks/{original['id']}", json={"title": f"  {title} \t"}
    )

    expected = {**original, "title": title}
    assert response.status_code == 200
    assert response.json() == expected
    assert_saved_task(client, expected)


def test_patch_empty_object_rejected_without_changing_task(client):
    original = create_task(client)

    response = client.patch(f"/tasks/{original['id']}", json={})

    assert response.status_code == 422
    assert "detail" in response.json()
    assert_saved_task(client, original)


@pytest.mark.parametrize(
    "update",
    [{"title": "New title"}, {"done": True}, {"title": "New title", "done": False}],
)
def test_patch_unknown_id_returns_not_found(client, update):
    response = client.patch("/tasks/123456", json=update)

    assert response.status_code == 404
    assert response.json() == {"detail": "Task not found"}
    response = client.get("/tasks")
    assert response.status_code == 200
    assert response.json() == []


def test_patch_ignores_attempts_to_change_immutable_fields(client):
    original = create_task(client)

    response = client.patch(
        f"/tasks/{original['id']}",
        json={
            "id": original["id"] + 1000,
            "created_at": "2000-01-01T00:00:00Z",
            "title": "Updated title",
            "done": True,
        },
    )

    expected = {**original, "title": "Updated title", "done": True}
    assert response.status_code == 200
    assert response.json() == expected
    assert_saved_task(client, expected)
    response = client.get("/tasks")
    assert response.status_code == 200
    assert response.json() == [expected]
