    "use strict";

    const form = document.getElementById("task-form");
    const input = document.getElementById("task-input");
    const search = document.getElementById("search-input");
    const list = document.getElementById("task-list");
    const empty = document.querySelector(".empty");
    const error = document.querySelector(".error");
    const addButton = form.querySelector("button");
    const filters = [
      [document.getElementById("filter-all"), ""],
      [document.getElementById("filter-todo"), "todo"],
      [document.getElementById("filter-done"), "done"]
    ];
    let status = "";
    let requestVersion = 0;

    function showError() {
      error.textContent = "Không thể thực hiện. Vui lòng thử lại.";
      error.hidden = false;
    }

    function clearError() {
      error.hidden = true;
      error.textContent = "";
    }

    async function api(url, options = {}) {
      const response = await fetch(url, options);
      if (!response.ok) {
        throw new Error("API request failed");
      }
      return response.status === 204 ? null : response.json();
    }

    function render(tasks) {
      list.replaceChildren();
      empty.hidden = tasks.length !== 0;
      for (const task of tasks) {
        const row = document.createElement("li");
        row.className = "task";

        const checkbox = document.createElement("input");
        checkbox.type = "checkbox";
        checkbox.id = `task-${task.id}`;
        checkbox.checked = task.done;

        const title = document.createElement("label");
        title.htmlFor = checkbox.id;
        title.className = task.done ? "task-title completed" : "task-title";
        title.textContent = task.title;

        const remove = document.createElement("button");
        remove.type = "button";
        remove.className = "delete";
        remove.textContent = "Xóa";
        remove.setAttribute("aria-label", `Xóa: ${task.title}`);

        async function mutate(options) {
          requestVersion++;
          clearError();
          checkbox.disabled = true;
          remove.disabled = true;
          try {
            await api(`/tasks/${task.id}`, options);
            await loadTasks();
          } catch {
            checkbox.checked = task.done;
            showError();
          } finally {
            checkbox.disabled = false;
            remove.disabled = false;
          }
        }

        checkbox.addEventListener("change", () => {
          const done = checkbox.checked;
          checkbox.checked = task.done;
          mutate({
            method: "PATCH",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ done })
          });
        });
        remove.addEventListener("click", () => mutate({ method: "DELETE" }));
        row.append(checkbox, title, remove);
        list.append(row);
      }
    }

    async function loadTasks() {
      const version = ++requestVersion;
      const params = new URLSearchParams();
      if (status) params.set("status", status);
      if (search.value) params.set("q", search.value);
      clearError();
      try {
        const tasks = await api(`/tasks${params.size ? `?${params}` : ""}`);
        if (version === requestVersion) render(tasks);
      } catch {
        if (version === requestVersion) showError();
      }
    }

    form.addEventListener("submit", async (event) => {
      event.preventDefault();
      if (addButton.disabled) return;
      const title = input.value.trim();
      if (!title) {
        showError();
        input.focus();
        return;
      }
      clearError();
      requestVersion++;
      addButton.disabled = true;
      const submittedValue = input.value;
      try {
        await api("/tasks", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ title })
        });
        if (input.value === submittedValue) input.value = "";
        input.focus();
        await loadTasks();
      } catch {
        showError();
      } finally {
        addButton.disabled = false;
      }
    });

    for (const [button, value] of filters) {
      button.addEventListener("click", () => {
        status = value;
        for (const [filter, filterValue] of filters) {
          filter.setAttribute("aria-pressed", String(filterValue === status));
        }
        loadTasks();
      });
    }
    search.addEventListener("input", loadTasks);
    loadTasks();
  </script>
