import pytest


def create_task(client, title="Original title"):
    response = client.post("/tasks", json={"title": title})
    assert response.status_code == 201
    return response.json()


def assert_persisted_task(client, expected):
    response = client.get(f"/tasks/{expected['id']}")
    assert response.status_code == 200
    assert response.json() == expected


def test_patch_title_only_preserves_other_fields(client):
    original = create_task(client)
    response = client.patch(
        f"/tasks/{original['id']}", json={"title": "  Updated title \t\n"}
    )

    expected = {**original, "title": "Updated title"}
    assert response.status_code == 200
    assert response.json() == expected
    assert_persisted_task(client, expected)


def test_patch_done_supports_true_and_explicit_false(client):
    original = create_task(client)

    for done in (True, False):
        response = client.patch(
            f"/tasks/{original['id']}", json={"done": done}
        )
        expected = {**original, "done": done}
        assert response.status_code == 200
        assert response.json() == expected
        assert response.json()["done"] is done
        assert_persisted_task(client, expected)


def test_patch_title_and_done_together(client):
    original = create_task(client)
    response = client.patch(
        f"/tasks/{original['id']}",
        json={"title": "  Completed task  ", "done": True},
    )

    expected = {**original, "title": "Completed task", "done": True}
    assert response.status_code == 200
    assert response.json() == expected
    assert_persisted_task(client, expected)


@pytest.mark.parametrize("length", [1, 100])
def test_patch_title_accepts_trimmed_length_boundaries(client, length):
    original = create_task(client)
    title = "x" * length
    response = client.patch(
        f"/tasks/{original['id']}", json={"title": f" \t{title}\n "}
    )

    expected = {**original, "title": title}
    assert response.status_code == 200
    assert response.json() == expected
    assert_persisted_task(client, expected)


@pytest.mark.parametrize("title", ["", " \t\n ", "x" * 101])
def test_invalid_combined_patch_does_not_persist_any_change(client, title):
    original = create_task(client)
    response = client.patch(
        f"/tasks/{original['id']}", json={"title": title, "done": True}
    )

    assert response.status_code == 422
    assert "detail" in response.json()
    assert_persisted_task(client, original)


def test_empty_patch_is_rejected_without_changes(client):
    original = create_task(client)
    response = client.patch(f"/tasks/{original['id']}", json={})

    assert response.status_code == 422
    assert "detail" in response.json()
    assert_persisted_task(client, original)


def test_patch_unknown_id_returns_task_not_found(client):
    original = create_task(client)
    response = client.patch(
        f"/tasks/{original['id'] + 1}",
        json={"title": "Valid update", "done": True},
    )

    assert response.status_code == 404
    assert response.json() == {"detail": "Task not found"}
    assert_persisted_task(client, original)
    listing = client.get("/tasks")
    assert listing.status_code == 200
    assert listing.json() == [original]


@pytest.mark.parametrize(
    "immutable_fields",
    [
        {"id": 999999},
        {"created_at": "2000-01-01T00:00:00+00:00"},
    ],
)
def test_patch_cannot_change_immutable_fields(client, immutable_fields):
    original = create_task(client)
    response = client.patch(
        f"/tasks/{original['id']}",
        json={"title": "Edited title", **immutable_fields},
    )

    # Rejecting immutable fields or ignoring them both preserve immutability.
    assert response.status_code in (200, 422)
    if response.status_code == 200:
        expected = {**original, "title": "Edited title"}
        assert response.json() == expected
    else:
        assert "detail" in response.json()
        expected = original

    assert_persisted_task(client, expected)
    listing = client.get("/tasks")
    assert listing.status_code == 200
    assert listing.json() == [expected]
