import pytest


def create_task(client, title="Original title"):
    response = client.post("/tasks", json={"title": title})
    assert response.status_code == 201
    return response.json()


def assert_persisted(client, task):
    response = client.get(f"/tasks/{task['id']}")
    assert response.status_code == 200
    assert response.json() == task


def test_patch_title_trims_and_preserves_omitted_fields(client):
    original = create_task(client)

    response = client.patch(
        f"/tasks/{original['id']}", json={"title": "  Updated title \t\n"}
    )

    assert response.status_code == 200
    expected = {**original, "title": "Updated title"}
    assert response.json() == expected
    assert_persisted(client, expected)


def test_patch_done_can_toggle_both_directions_without_changing_title(client):
    original = create_task(client)

    for done in (True, False):
        response = client.patch(
            f"/tasks/{original['id']}", json={"done": done}
        )
        assert response.status_code == 200
        expected = {**original, "done": done}
        assert response.json() == expected
        assert response.json()["done"] is done
        assert_persisted(client, expected)


def test_patch_title_and_done_together_persists_in_list(client):
    original = create_task(client)
    newer = create_task(client, "Another task")

    response = client.patch(
        f"/tasks/{original['id']}",
        json={"title": "  Revised  ", "done": True},
    )

    assert response.status_code == 200
    expected = {**original, "title": "Revised", "done": True}
    assert response.json() == expected
    assert_persisted(client, expected)
    listing = client.get("/tasks")
    assert listing.status_code == 200
    assert listing.json() == [newer, expected]


@pytest.mark.parametrize("title", ["x", "x" * 100])
def test_patch_title_accepts_trimmed_length_boundaries(client, title):
    original = create_task(client)

    response = client.patch(
        f"/tasks/{original['id']}", json={"title": f" \t{title}\n "}
    )

    assert response.status_code == 200
    expected = {**original, "title": title}
    assert response.json() == expected
    assert_persisted(client, expected)


@pytest.mark.parametrize("title", ["", " \t\n ", " " + "x" * 101 + " "])
def test_patch_invalid_title_does_not_partially_update_done(client, title):
    original = create_task(client)
    completed = client.patch(
        f"/tasks/{original['id']}", json={"done": True}
    )
    assert completed.status_code == 200
    expected = {**original, "done": True}

    response = client.patch(
        f"/tasks/{original['id']}", json={"title": title, "done": False}
    )

    assert response.status_code == 422
    assert "detail" in response.json()
    assert_persisted(client, expected)


def test_patch_empty_object_is_rejected_without_changes(client):
    original = create_task(client)

    response = client.patch(f"/tasks/{original['id']}", json={})

    assert response.status_code == 422
    assert "detail" in response.json()
    assert_persisted(client, original)


def test_patch_unknown_id_returns_exact_not_found_error(client):
    original = create_task(client)

    response = client.patch(
        f"/tasks/{original['id'] + 1}",
        json={"title": "Valid update", "done": True},
    )

    assert response.status_code == 404
    assert response.json() == {"detail": "Task not found"}
    assert_persisted(client, original)
    listing = client.get("/tasks")
    assert listing.status_code == 200
    assert listing.json() == [original]


@pytest.mark.parametrize(
    "protected_fields",
    [
        {"id": 999999},
        {"created_at": "2000-01-01T00:00:00+00:00"},
    ],
)
def test_patch_cannot_change_identity_or_creation_timestamp(client, protected_fields):
    original = create_task(client)

    response = client.patch(
        f"/tasks/{original['id']}",
        json={"title": "Allowed update", **protected_fields},
    )

    # The API may reject protected fields or ignore them, but never modify them.
    assert response.status_code in (200, 422)
    if response.status_code == 200:
        expected = {**original, "title": "Allowed update"}
        assert response.json() == expected
    else:
        assert "detail" in response.json()
        expected = original
    assert_persisted(client, expected)
    listing = client.get("/tasks")
    assert listing.status_code == 200
    assert listing.json() == [expected]
